retry        retryBudget
retryStopped bool
s            *sys.Session
in           ShapeInput
repo         *git.Repo
root         string
slug         string
cfg          *project.Config
role         project.Role
ev           *Evidence
rd           *verify.Readiness
client       *provider.Client
stateDir     string
ext    executor.Executor
extMax int
started       time.Time
toolDefs      []any
measure       ContextMeasure
originals     map[string]original
proposed      map[string]string // path to proposed content, accumulated over the run
declaredSteps []string          // proposed JavaScript steps once declared in Acceptance:
ready         *verify.Ready
requests      int
preparationRefused []preparationSignature
inspected     bool             // a read, list or search tool answered in this conversation
externalReads map[string]bool  // paths read by the external shaper in its current turn
docs          []map[string]any // documentation tool results of this conversation
window        *window
cacheID       string // this conversation's cache identity
ledger  *decisionLedger
round   int
tracked map[string]bool // the files tracked at HEAD, once listed
submissions  int // submissions made in this run
priorInvalid int // invalid submissions before the current attempt
request        string         // the request text of this shaping
decisionChecks int            // decision check calls made
decisionUsage  provider.Usage // the native decision checks' tokens
decisionRounds int            // the external decision check sessions' rounds
rounds        []map[string]any // the questions and answers of the shaping state, in round order
literalChecks int              // literal check calls made
literalUsage  provider.Usage   // the native literal checks' tokens
literalRounds int              // the external literal check sessions' rounds
earlier             string         // the earlier questions and answers, as the shaper reads them
questionChecks      int            // question check calls made
questionUsage       provider.Usage // the native question checks' tokens
questionRounds      int            // the external question check sessions' rounds
evidencedRefusals   int            // evidenced environment-only question submissions in this run
refusedQuestionSets int
questionRefusals    []classCount      // the classes of the questions the question checks refused, in order of first refusal
probed              map[string]bool   // the commands of the probe calls of this run
probeTexts          map[string]string // the latest answer text of each probed command of this run
probeOutputs        map[string]capturedProbeOutput
readTexts           map[string]string // the latest answer text of the read_file calls of the main conversation, by cleaned path
ranCommand          bool              // the external session completed a Bash call
readPaths           map[string]bool   // the cleaned path arguments of the read_file calls of the main conversation
listedPaths         map[string]bool   // the cleaned path arguments of the list_files calls of the main conversation
