}
type readinessReview struct {
ready        *verify.Ready
packageHash  string
evidenceHash string
}
func (sh *shaping) toolSpan(fn func() error) error {
t := sh.ev.Millis()
defer func() { sh.ev.ShaperTool(t, sh.ev.Millis()) }()
return fn()
}
func (sh *shaping) elapsed() int64 { return time.Since(sh.started).Milliseconds() / 1000 }
func (sh *shaping) progress(line string) {
sh.s.Progress(fmt.Sprintf("%s (%d s)", line, sh.elapsed()))
}
func (sh *shaping) overlay() map[string][]byte { return overlayOf(sh.proposed) }
func overlayOf(proposed map[string]string) map[string][]byte {
m := make(map[string][]byte, len(proposed))
for p, c := range proposed {
m[p] = []byte(c)
}
return m
}
func (sh *shaping) mainTools() []string {
return []string{tools.ReadFileTool, tools.ViewImageTool, tools.ListFilesTool, tools.SearchTextTool, ProbeTool, tools.DocumentationTool}
}
type outcomeKind int
const (
outNone outcomeKind = iota
outInvalid
outObservations
outQuestions
outBlocked
outReady
outNoTool
outPrecheck        // a submit call that was pre-checked and not counted
outQuestionRefused // a well-formed question set refused by its own bounded gate
)
type outcome struct {
kind      outcomeKind
detail    string // outNoTool: the stop's detail line
problems  []string
questions []map[string]any
paths     []string
reason    string
}
func (sh *shaping) shape(ctx context.Context, st *state) (int, error) {
sh.started = time.Now()
t0 := sh.started
role := sh.role
restored, err := sh.restoreDraftHelpers()
if err != nil {
return 0, err
}
defs := ShaperToolDefinitions(sh.mainTools()...)
defs = append(defs, ShaperToolDefinitions(ProposeFilesTool, SubmitTool)...)
sh.toolDefs = agent.AsAny(defs)
protected, err := project.Protected(sh.root, sh.cfg)
if err != nil {
return 0, err
}
selected, _, err := Navigation(sh.repo)
if err != nil {
return 0, err
}
blocks, err := contextBlocks(promptInput{root: sh.root, slug: sh.slug, cfg: sh.cfg, state: st, protected: protected, selected: selected, ledger: sh.ledger, current: sh.checkoutDigest, restored: restored})
if err != nil {
return 0, err
}
sh.request = st.Request
sh.earlier = roundsText(st.Rounds)
sh.rounds = st.Rounds
input := []any{map[string]any{"role": "user", "content": blocks}}
sh.window = newShapeWindow(sh.root, sh.slug, input)
sh.cacheID = startConversation(sh.ev, "shape")
sh.rd.BeforeRecord = func() error { return sh.window.validate(sh.root) }
sh.rd.Gate = func(ready *verify.Ready) error {
if err := readinessGate(ready); err != nil {
return err
}
if err := sh.preparationGate(ready); err != nil {
return err
}
return sh.unpassableGate(ctx, ready)
}
var res outcome
var usageLine string
if sh.ext != nil {
var x *extSession
res, x, err = sh.converseExternal(ctx, blocks)
if x != nil {
usageLine = fmt.Sprintf("shape %s/%s %s %d round(s) wall_ms=%d", role.Model, role.Effort, executor.ClaudeCode, x.rounds+sh.decisionRounds+sh.literalRounds+sh.contractRounds+sh.questionRounds, time.Since(t0).Milliseconds())
}
if err != nil {
return 0, err
}
} else {
var usage provider.Usage
res, usage, err = sh.converse(ctx, input)
if err != nil {
if e, ok := sys.AsError(err); ok && e.Class == "provider" {
return 0, sh.providerFailed(e)
}
return 0, err
}
usageLine = fmt.Sprintf("shape %s/%s %s wall_ms=%d", role.Model, role.Effort, sh.decisionUsage.Add(sh.literalUsage).Add(sh.contractUsage).Add(sh.questionUsage).Add(usage).Line(), time.Since(t0).Milliseconds())
}
switch res.kind {
case outInvalid:
if sh.incomplete {
e := sys.Fail("shape", "incomplete_package", fmt.Sprintf("blocked: the shaper could not complete the package within %d attempts", submissionRetryLimit(sh.in.SubmissionRetryLimit)), 1)
gap := sh.incompleteRefusal
problems := sh.declaredGaps(sh.proposed)
if gap.gate == "validation" {
problems = append(slices.Clone(gap.problems), problems...)
}
e.Lines = append([]string{fmt.Sprintf("unresolved gap (attempt %d, gate %s):", gap.attempt, gap.gate)}, problems...)
e.Lines = append(append(e.Lines, sh.earliestLines()...), sh.refusalCountsLines()...)
return 0, e
}
if len(sh.originals) > 0 {
if sh.lastGate == contractGate {
if err := sh.writeContractContradictions(sh.contractLines); err != nil {
return 0, err
}
}
problems := append(append(slices.Clone(res.problems), sh.earliestLines()...), sh.refusalCountsLines()...)
data, err := json.Marshal(draftRefusal{Gate: sh.lastGate, Problems: problems})
if err != nil {
return 0, err
}
if err := os.WriteFile(draftRefusalPath(sh.root, sh.slug), data, 0600); err != nil {
return 0, err
}
var files []string
for p := range sh.originals {
files = append(files, p)
}
return 0, draftDiagnostic(sh.root, sh.slug, "not_ready", "the Intent is not ready to build", 1, append([]string{"Refusing check: " + sh.lastGate}, problems...), files)
}
e := sys.Fail("shape", "invalid_output", fmt.Sprintf("the shaper's output was not a valid Intent after %d attempts", submissionRetryLimit(sh.in.SubmissionRetryLimit)), 1)
e.Lines = append(append(slices.Clone(res.problems), sh.earliestLines()...), sh.refusalCountsLines()...)
return 0, e
case outNoTool:
e := sys.Fail("shape", "invalid_output", res.detail, 1)
e.Lines = res.problems
return 0, e
case outQuestions:
round := map[string]any{"questions": questionList(res.questions), "answers": map[string]any{}}
st.Rounds = append(st.Rounds, round)
if err := saveState(sh.stateDir, st); err != nil {
return 0, err
}
list := make([]numbered, len(res.questions))
for i, q := range res.questions {
list[i] = numbered{i + 1, q}
}
if err := writeQuestions(sh.root, sh.stateDir, sh.slug, list); err != nil {
return 0, err
}
return printQuestions(sh.s, sh.slug, list), nil
case outBlocked:
return sh.printBlocked(res), nil
}
if err := sh.window.validate(sh.root); err != nil {
return 0, err
}
rounds := make([]map[string]any, len(st.Rounds))
copy(rounds, st.Rounds)
origin := project.SourceOrigin{
Head: textOf(st.Origin["head"]), Tree: textOf(st.Origin["tree"]), Configuration: textOf(st.Origin["configuration"]),
}
if err := project.CaptureSource(sh.root, sh.slug, sh.cfg, project.ShapeSource{
Request: st.Request, SourcePath: st.SourcePath, Rounds: rounds, Origin: origin,
}); err != nil {
return 0, err
}
if err := sh.rd.RecordPass(sh.s, sh.slug, sh.ready); err != nil {
return 0, err
}
if err := os.Remove(draftRefusalPath(sh.root, sh.slug)); err != nil && !errors.Is(err, fs.ErrNotExist) {
return 0, err
}
os.Remove(filepath.Join(sh.stateDir, "state.json"))
os.Remove(filepath.Join(sh.stateDir, questionsFile))
os.Remove(filepath.Join(sh.stateDir, contractContradictionsFile))
var added []string
for p, o := range sh.originals {
if o.absent {
added = append(added, p)
}
}
return sh.printReady(added, usageLine), nil
}
func questionList(qs []map[string]any) []any {
out := make([]any, len(qs))
for i, q := range qs {
out[i] = q
}
return out
}
func (sh *shaping) providerFailed(e *sys.Error) error {
if sh.providerErr != nil {
return sh.providerErr(e)
}
e = agent.WithOriginHint(e)
sh.s.Out(e.Render())
if kept := sortedKeys(sh.proposed); len(kept) > 0 {
if err := sh.keepProposals(); err != nil {
return err
}
sh.s.Puts(fmt.Sprintf("kogen: shaping kept %d proposed file(s) under %s: %s", len(kept), proposedDir(sh.slug), strings.Join(kept, ", ")))
}
var retry string
if sh.in.RequestPath == "" {
retry = "kogen intent shape " + sh.slug + " - with the original request on stdin (or the same answers if questions are pending)"
} else {
retry = "kogen intent shape " + sh.slug + " " + ShellQuote(sh.in.RequestPath) + " with that request file (or the same answers file if questions are pending)"
}
sentence := "shaping stopped on a provider error after its retries; the failed request wrote no files. Rerun " + retry + ", or write the Intent yourself."
if e.Reason == "login" || e.Reason == "usage_limit" {
sentence = "shaping stopped on a provider error that retrying cannot fix; the failed request wrote no files. Fix the account, then rerun " + retry + "."
}
return sys.Fail("shape", "provider_failed", sentence, 4)
}
func (sh *shaping) converse(ctx context.Context, input []any) (outcome, provider.Usage, error) {
var usage provider.Usage
turns := newTurns("shape")
defer func(){ turns.countsBound(sh.ev, sh.requests) }()
home := sh.s.Getenv("HOME")
if home == "" {
home, _ = os.UserHomeDir()
}
redactor := verify.NewRedactor(sh.s.Env, home)
sinceSubmit := 0
noToolStreak := 0
var last lastSubmission
var lastAnswer string
for {
sh.requests++
sh.s.Progress(fmt.Sprintf("kogen: shaping (request %d, %d s)", sh.requests, sh.elapsed()))
t0 := time.Now()
revision, err := CurrentRevision(sh.repo)
if err != nil {
return outcome{}, usage, err
}
manifest, err := sh.writeManifest(revision)
if err != nil {
return outcome{}, usage, err
}
enc, err := project.EncodeJSON(manifest)
if err != nil {
return outcome{}, usage, err
}
input = append(input, map[string]any{"role": "user", "content": "Cumulative proposal manifest: " + string(enc)})
event, err := selectionEvent(input, manifest, sh.measure)
if err != nil {
return outcome{}, usage, err
}
sh.ev.Record(event)
req := conversationRequest(provider.Request{
Role: ProviderRole(sh.role), Instructions: ShaperInstructions(), Input: input, Tools: sh.toolDefs,
Scope: sh.ev.Dir, Context: map[string]any{"phase": "shape", "role": "shape", "slug": sh.slug},
}, sh.cacheID)
turns.apply(&req)
input, err = sh.window.prepare(windowPrep{role: req.Role,
root: sh.root, ev: sh.ev, progress: sh.progress,
render: func(items []any) map[string]any { r := req; r.Input = items; return sh.client.Body(r) },
state: func(head windowRef, count int, snapshot map[string]any, observations []any) map[string]any {
state := turns.extend(map[string]any{
"history": map[string]any{"head": head.value(), "count": count}, "manifest": manifest,
"declared_steps": nonNilStrings(sh.declaredSteps), "inspected": sh.inspected,
