var probeSummary = regexp.MustCompile(`\Aexit status: -?\d+\ntimed_out: (?:true|false)\nwall: [\d.]+ s(?:\n|\z)`)
func (sh *shaping) runTool(ctx context.Context, c tools.Call) (tools.Output, error) {
args := c.Args()
tl := sh.agentTools(ctx, sh.mainTools())
sh.noteReach(c.Name, args)
if c.Name != ProbeTool {
out, err := tl.Run(c.Name, args)
if err == nil && c.Name == tools.ReadFileTool {
if sh.readTexts == nil {
sh.readTexts = map[string]string{}
}
path, _ := args["path"].(string)
sh.readTexts[cleanCitedPath(path)] = out.Text
}
return out, err
}
if capture, present := args["capture_output"]; present {
enabled, ok := capture.(bool)
if !ok {
return tools.Output{Text: "error: capture_output must be a boolean"}, nil
}
if enabled {
tl.Probe = func(command string, files any) (string, error) { return sh.probe(ctx, command, files, true) }
}
}
sh.progress("kogen: probe: " + textOf(args["command"]))
var out tools.Output
_, err := sh.ev.ProbeText(nil, func() (string, error) {
var err error
out, err = tl.Run(c.Name, args)
return out.Text, err
})
if err != nil {
return out, err
}
summary := "tool error"
if m := probeSummary.FindString(out.Text); m != "" {
summary = strings.ReplaceAll(strings.TrimSpace(m), "\n", "; ")
}
sh.progress("kogen: probe result: " + summary)
if sh.probeTexts == nil {
sh.probeTexts = map[string]string{}
}
sh.probeTexts[textOf(args["command"])] = out.Text
return out, nil
}
