func titleLength(s string) int {
n, ri := 0, 0
var prev rune
for _, r := range s {
regional := r >= 0x1F1E6 && r <= 0x1F1FF
pictographic := r >= 0x1F300 && r <= 0x1FAFF || r >= 0x2600 && r <= 0x27BF || r == 0x2764 || r == 0x2B50
attach := n > 0 && (prev == '\r' && r == '\n' || unicode.In(r, unicode.Mn, unicode.Me, unicode.Mc) || r == 0x200C || r == 0x200D || r >= 0x1F3FB && r <= 0x1F3FF || r >= 0xE0020 && r <= 0xE007F || prev == 0x200D && pictographic || regional && ri%2 == 1)
if regional {
ri++
} else {
ri = 0
}
if !attach {
n++
}
prev = r
}
return n
}
func shortenTitle(title string) string {
r := []rune(title)
if len(r) > 50 {
cut := 50
if r[50] != ' ' {
for cut > 0 && r[cut-1] != ' ' {
cut--
}
if cut == 0 {
cut = 50
}
}
r = r[:cut]
}
return strings.TrimRightFunc(string(r), func(c rune) bool { return unicode.IsSpace(c) || unicode.IsPunct(c) })
}
func submissionRetryLimit(limit int) int {
if limit <= 0 {
return 3
}
return limit
}

