kind = "boolean"
case nil:
kind = "null"
case map[string]any:
default:
kind = "number"
}
parts = append(parts, key+" ("+kind+")")
}
if len(parts) == 0 {
return "none of questions, files or blocked"
}
return strings.Join(parts, ", ")
