if e, ok := sys.AsError(err); ok && e.Class == "provider" {
return 0, sh.providerFailed(e)
}
return 0, err
}
usageLine = fmt.Sprintf("shape %s/%s %s wall_ms=%d", role.Model, role.Effort, sh.decisionUsage.Add(sh.literalUsage).Add(sh.contractUsage).Add(sh.questionUsage).Add(usage).Line(), time.Since(t0).Milliseconds())
}
switch res.kind {
case outInvalid:
if sh.incomplete {
e := sys.Fail("shape", "incomplete_package", fmt.Sprintf("blocked: the shaper could not complete the package within %d attempts", submissionRetryLimit(sh.in.SubmissionRetryLimit)), 1)
gap := sh.incompleteRefusal
problems := sh.declaredGaps(sh.proposed)
if gap.gate == "validation" {
problems = append(slices.Clone(gap.problems), problems...)
}
e.Lines = append([]string{fmt.Sprintf("unresolved gap (attempt %d, gate %s):", gap.attempt, gap.gate)}, problems...)
e.Lines = append(append(e.Lines, sh.earliestLines()...), sh.refusalCountsLines()...)
return 0, e
}
if len(sh.originals) > 0 {
if sh.lastGate == contractGate {
if err := sh.writeContractContradictions(sh.contractLines); err != nil {
return 0, err
}
}
problems := append(append(slices.Clone(res.problems), sh.earliestLines()...), sh.refusalCountsLines()...)
data, err := json.Marshal(draftRefusal{Gate: sh.lastGate, Problems: problems})
if err != nil {
return 0, err
}
if err := os.WriteFile(draftRefusalPath(sh.root, sh.slug), data, 0600); err != nil {
return 0, err
}
var files []string
for p := range sh.originals {
files = append(files, p)
}
return 0, draftDiagnostic(sh.root, sh.slug, "not_ready", "the Intent is not ready to build", 1, append([]string{"Refusing check: " + sh.lastGate}, problems...), files)
}
e := sys.Fail("shape", "invalid_output", fmt.Sprintf("the shaper's output was not a valid Intent after %d attempts", submissionRetryLimit(sh.in.SubmissionRetryLimit)), 1)
e.Lines = append(append(slices.Clone(res.problems), sh.earliestLines()...), sh.refusalCountsLines()...)
return 0, e
case outNoTool:
e := sys.Fail("shape", "invalid_output", res.detail, 1)
e.Lines = res.problems
return 0, e
case outQuestions:
round := map[string]any{"questions": questionList(res.questions), "answers": map[string]any{}}
st.Rounds = append(st.Rounds, round)
if err := saveState(sh.stateDir, st); err != nil {
return 0, err
}
list := make([]numbered, len(res.questions))
for i, q := range res.questions {
list[i] = numbered{i + 1, q}
}
if err := writeQuestions(sh.root, sh.stateDir, sh.slug, list); err != nil {
return 0, err
}
return printQuestions(sh.s, sh.slug, list), nil
case outBlocked:
return sh.printBlocked(res), nil
}
if err := sh.window.validate(sh.root); err != nil {
return 0, err
}
rounds := make([]map[string]any, len(st.Rounds))
copy(rounds, st.Rounds)
origin := project.SourceOrigin{
Head: textOf(st.Origin["head"]), Tree: textOf(st.Origin["tree"]), Configuration: textOf(st.Origin["configuration"]),
}
if err := project.CaptureSource(sh.root, sh.slug, sh.cfg, project.ShapeSource{
Request: st.Request, SourcePath: st.SourcePath, Rounds: rounds, Origin: origin,
}); err != nil {
return 0, err
}
if err := sh.rd.RecordPass(sh.s, sh.slug, sh.ready); err != nil {
return 0, err
}
if err := os.Remove(draftRefusalPath(sh.root, sh.slug)); err != nil && !errors.Is(err, fs.ErrNotExist) {
return 0, err
}
os.Remove(filepath.Join(sh.stateDir, "state.json"))
os.Remove(filepath.Join(sh.stateDir, questionsFile))
os.Remove(filepath.Join(sh.stateDir, contractContradictionsFile))
var added []string
for p, o := range sh.originals {
if o.absent {
added = append(added, p)
}
}
return sh.printReady(added, usageLine), nil
}
func questionList(qs []map[string]any) []any {
out := make([]any, len(qs))
for i, q := range qs {
out[i] = q
}
return out
}
func (sh *shaping) providerFailed(e *sys.Error) error {
if sh.providerErr != nil {
return sh.providerErr(e)
}
e = agent.WithOriginHint(e)
sh.s.Out(e.Render())
if kept := sortedKeys(sh.proposed); len(kept) > 0 {
if err := sh.keepProposals(); err != nil {
return err
}
sh.s.Puts(fmt.Sprintf("kogen: shaping kept %d proposed file(s) under %s: %s", len(kept), proposedDir(sh.slug), strings.Join(kept, ", ")))
}
var retry string
if sh.in.RequestPath == "" {
retry = "kogen intent shape " + sh.slug + " - with the original request on stdin (or the same answers if questions are pending)"
} else {
retry = "kogen intent shape " + sh.slug + " " + ShellQuote(sh.in.RequestPath) + " with that request file (or the same answers file if questions are pending)"
}
sentence := "shaping stopped on a provider error after its retries; the failed request wrote no files. Rerun " + retry + ", or write the Intent yourself."
if e.Reason == "login" || e.Reason == "usage_limit" {
sentence = "shaping stopped on a provider error that retrying cannot fix; the failed request wrote no files. Fix the account, then rerun " + retry + "."
}
return sys.Fail("shape", "provider_failed", sentence, 4)
}
func (sh *shaping) converse(ctx context.Context, input []any) (outcome, provider.Usage, error) {
var usage provider.Usage
turns := newTurns("shape")
defer func(){ turns.countsBound(sh.ev, sh.requests) }()
home := sh.s.Getenv("HOME")
if home == "" {
home, _ = os.UserHomeDir()
}
redactor := verify.NewRedactor(sh.s.Env, home)
sinceSubmit := 0
noToolStreak := 0
var last lastSubmission
var lastAnswer string
for {
sh.requests++
sh.s.Progress(fmt.Sprintf("kogen: shaping (request %d, %d s)", sh.requests, sh.elapsed()))
t0 := time.Now()
revision, err := CurrentRevision(sh.repo)
if err != nil {
return outcome{}, usage, err
}
manifest, err := sh.writeManifest(revision)
if err != nil {
return outcome{}, usage, err
}
enc, err := project.EncodeJSON(manifest)
if err != nil {
return outcome{}, usage, err
}
input = append(input, map[string]any{"role": "user", "content": "Cumulative proposal manifest: " + string(enc)})
event, err := selectionEvent(input, manifest, sh.measure)
if err != nil {
return outcome{}, usage, err
}
sh.ev.Record(event)
req := conversationRequest(provider.Request{
Role: ProviderRole(sh.role), Instructions: ShaperInstructions(), Input: input, Tools: sh.toolDefs,
Scope: sh.ev.Dir, Context: map[string]any{"phase": "shape", "role": "shape", "slug": sh.slug},
}, sh.cacheID)
turns.apply(&req)
input, err = sh.window.prepare(windowPrep{role: req.Role,
root: sh.root, ev: sh.ev, progress: sh.progress,
render: func(items []any) map[string]any { r := req; r.Input = items; return sh.client.Body(r) },
state: func(head windowRef, count int, snapshot map[string]any, observations []any) map[string]any {
state := turns.extend(map[string]any{
"history": map[string]any{"head": head.value(), "count": count}, "manifest": manifest,
"declared_steps": nonNilStrings(sh.declaredSteps), "inspected": sh.inspected,
"documentation": snapshot, "invalid_submissions": turns.invalid, "readiness": windowReadyRecord(sh.ready),
"assistant_observations": observations,
})
if noToolStreak > 0 {
state["consecutive_no_tool_turns"] = noToolStreak
}
return state
},
}, input)
if err != nil {
return outcome{}, usage, err
}
req.Input = input
turns.announce(req, sh.role, sh.ev)
call := sh.ev.BeginCall("shape", "", revision.Map(), "main shaping", sh.role).Sized(sh.client, req)
resp, err := tools.Deliver(input, "shape", sh.ev.Record, func() (*provider.Response, error) {
sent := sh.ev.Millis()
r, err := sh.client.Respond(ctx, sh.s, req, call)
call.End(r, err)
sh.ev.ShaperModel(sent, sh.ev.Millis())
return r, err
})
if err != nil {
return outcome{}, usage, err
}
sh.progress(fmt.Sprintf("kogen: shape response %s wall_ms=%d", resp.Usage.Line(), time.Since(t0).Milliseconds()))
usage = usage.Add(resp.Usage)
calls := tools.Calls(resp.Items)
input = append(input, tools.Replay(resp.Items)...)
toolFree := turns.answered(len(calls))
if toolFree {
noToolStreak++
sinceSubmit++
lastAnswer = sh.recordToolFreeAnswer(resp.Items, turns.noTool, redactor)
} else {
noToolStreak = 0
}
if sh.requests > shapeRequestCap { return requestCapStop(last, lastAnswer), usage, nil }
var outputs []any
var result outcome
for _, c := range calls {
if err := sh.window.validate(sh.root); err != nil {
return outcome{}, usage, err
}
if result.kind != outNone {
outputs = append(outputs, toolOutput(c, "ignored: only one submit counts per response"))
continue
}
switch {
case c.Name == ProposeFilesTool:
var text string
err := sh.toolSpan(func() (err error) { text, err = sh.proposeFiles(c.Args()); return })
if err != nil {
return outcome{}, usage, err
}
outputs = append(outputs, toolOutput(c, text))
case c.Name == SubmitTool:
sh.priorInvalid = sh.retry.consecutive
text, r, err := sh.submit(ctx, c.Args())
if err != nil {
return outcome{}, usage, err
}
result = r
outputs = append(outputs, toolOutput(c, text))
default:
var out tools.Output
err := sh.toolSpan(func() (err error) { out, err = sh.runTool(ctx, c); return })
if err != nil {
return outcome{}, usage, err
}
sh.noteTool(c.Name, out)
if c.Name == tools.DocumentationTool {
row := sh.ev.RetainDocumentation(c.Args(), out.Text)
started, finished := DocumentationProgress(row)
sh.progress(started)
sh.progress(finished)
}
if e := tools.ReadEvent(c, out, "shape"); e != nil {
sh.ev.Record(e)
}
outputs = append(outputs, toolOutput(c, out))
}
}
input = append(input, outputs...)
switch {
case result.kind == outQuestionRefused:
sinceSubmit = 0
last = lastSubmission{kind: outInvalid, attempt: sh.submissions, gate: sh.lastGate, problems: sh.lastRefusal, earliest: sh.earliestLines()}
sh.ev.NextAttempt()
case result.kind == outInvalid:
turns.invalid++
if sh.retryStopped {
return result, usage, nil
}
sinceSubmit = 0
last = lastSubmission{kind: outInvalid, attempt: sh.submissions, gate: sh.lastGate, problems: sh.lastRefusal,
unchanged: sh.unchanged, earliest: sh.earliestLines()}
sh.ev.NextAttempt()
case result.kind == outObservations:
sinceSubmit = 0
last = lastSubmission{kind: outObservations, attempt: sh.submissions, path: sh.lastObservationsPath}
sh.ev.NextAttempt()
case result.kind == outBlocked, result.kind == outQuestions, result.kind == outReady:
return result, usage, nil
case toolFree:
if toolFreeExhausted(sinceSubmit) {
return noToolStop(last, lastAnswer), usage, nil
}
sh.ev.NextAttempt()
if sinceSubmit == 1 && last.repairable() {
turns.recover()
sh.ev.Record(last.recoveryEvent(sh.requests + 1))
input = append(input, map[string]any{"role": "user", "content": last.recoveryMessage()})
continue
}
input = append(input, map[string]any{"role": "user", "content": turns.reminder})
}
}
}
func (sh *shaping) converseExternal(ctx context.Context, blocks []any) (outcome, *extSession, error) { panic("outside bounded native controls") }
func nonNilStrings(s []string) []string {
if s == nil {
return []string{}
}
return s
}
func (sh *shaping) noteTool(name string, out tools.Output) {
switch name {
case tools.ReadFileTool, tools.ListFilesTool, tools.SearchTextTool:
sh.inspected = true
case tools.DocumentationTool:
var result map[string]any
if err := json.Unmarshal([]byte(out.Text), &result); err == nil && result != nil {
sh.docs = append(sh.docs, result)
sh.window.documentation = sh.docs
}
}
}
func proposedDir(slug string) string {
return ".kogen/local/shaping/" + slug + "/proposed/"
}
func (sh *shaping) keepProposals() error {
for _, p := range sortedKeys(sh.proposed) {
dest := filepath.Join(sh.root, ".kogen/local/shaping", sh.slug, "proposed", p)
if err := os.MkdirAll(filepath.Dir(dest), 0o755); err != nil {
return err
}
if err := os.WriteFile(dest, []byte(sh.proposed[p]), 0o666); err != nil {
return err
}
}
return nil
}
func (sh *shaping) proposeFiles(args map[string]any) (string, error) {
list, _ := args["files"].([]any)
var sub submission
problems := []string{"propose_files takes a non-empty files list"}
if len(list) > 0 {
var refProblem string
list, refProblem = sh.expandProbeOutputs(list)
if refProblem != "" {
return "invalid proposal: " + refProblem + "\nNo files from this call were retained; earlier proposals are unchanged.", nil
}
var err error
if sub, problems, err = sh.validateFiles(list); err != nil {
return "", err
}
}
if problems != nil {
return "invalid proposal:\n" + strings.Join(problems, "\n") +
"\nNo files from this call were retained; earlier proposals are unchanged.", nil
}
paths := make([]string, len(sub.files))
for i, f := range sub.files {
sh.proposed[f.path] = f.content
paths[i] = f.path
}
if err := sh.keepProposals(); err != nil {
return "", err
}
joined := strings.Join(paths, ", ")
sh.ev.Record(map[string]any{"event": "proposal_retained", "paths": paths, "proposed": len(sh.proposed)})
sh.progress(fmt.Sprintf("kogen: shape proposal retained: %s (%d proposed file(s))", joined, len(sh.proposed)))
return fmt.Sprintf("retained: %s; %d proposed file(s) in all. Nothing was checked: submit to check the complete package.", joined, len(sh.proposed)), nil
}
func (sh *shaping) writeManifest(revision Revision) (map[string]any, error) {
proposed := []any{}
for _, p := range sortedKeys(sh.proposed) {
dest := filepath.Join(sh.root, ".kogen/local/shaping", sh.slug, "proposed", p)
if err := os.MkdirAll(filepath.Dir(dest), 0o755); err != nil {
return nil, err
}
if err := os.WriteFile(dest, []byte(sh.proposed[p]), 0o666); err != nil {
return nil, err
}
proposed = append(proposed, map[string]any{
"path": p, "sha256": ContentHash([]byte(sh.proposed[p])), "source": dest, "revision": revision.Map(),
})
}
originals := []any{}
for _, p := range sortedKeys(sh.originals) {
o := sh.originals[p]
if o.absent {
originals = append(originals, map[string]any{"path": p, "source": "original absence", "sha256": nil})
continue
}
dest := filepath.Join(sh.root, ".kogen/local/shaping", sh.slug, "original", p)
if err := os.MkdirAll(filepath.Dir(dest), 0o755); err != nil {
return nil, err
}
if err := os.WriteFile(dest, o.content, 0o666); err != nil {
return nil, err
}
originals = append(originals, map[string]any{"path": p, "source": dest, "sha256": ContentHash(o.content)})
}
manifest := map[string]any{"proposed": proposed, "originals": originals}
if captures := sh.capturedOutputManifest(); len(captures) > 0 {
manifest["captured_probe_outputs"] = captures
}
return manifest, nil
}
func (sh *shaping) noteReach(name string, args map[string]any) {
path, _ := args["path"].(string)
switch name {
case tools.ReadFileTool:
if sh.readPaths == nil {
sh.readPaths = map[string]bool{}
}
sh.readPaths[cleanCitedPath(path)] = true
case tools.ListFilesTool:
if sh.listedPaths == nil {
sh.listedPaths = map[string]bool{}
}
sh.listedPaths[cleanCitedPath(path)] = true
}
}
var probeSummary = regexp.MustCompile(`\Aexit status: -?\d+\ntimed_out: (?:true|false)\nwall: [\d.]+ s(?:\n|\z)`)
func (sh *shaping) runTool(ctx context.Context, c tools.Call) (tools.Output, error) {
args := c.Args()
tl := sh.agentTools(ctx, sh.mainTools())
sh.noteReach(c.Name, args)
if c.Name != ProbeTool {
out, err := tl.Run(c.Name, args)
if err == nil && c.Name == tools.ReadFileTool {
if sh.readTexts == nil {
sh.readTexts = map[string]string{}
}
path, _ := args["path"].(string)
sh.readTexts[cleanCitedPath(path)] = out.Text
}
return out, err
}
if capture, present := args["capture_output"]; present {
enabled, ok := capture.(bool)
if !ok {
return tools.Output{Text: "error: capture_output must be a boolean"}, nil
}
if enabled {
tl.Probe = func(command string, files any) (string, error) { return sh.probe(ctx, command, files, true) }
}
}
sh.progress("kogen: probe: " + textOf(args["command"]))
var out tools.Output
_, err := sh.ev.ProbeText(nil, func() (string, error) {
var err error
out, err = tl.Run(c.Name, args)
return out.Text, err
})
if err != nil {
return out, err
}
summary := "tool error"
if m := probeSummary.FindString(out.Text); m != "" {
summary = strings.ReplaceAll(strings.TrimSpace(m), "\n", "; ")
}
sh.progress("kogen: probe result: " + summary)
if sh.probeTexts == nil {
sh.probeTexts = map[string]string{}
}
sh.probeTexts[textOf(args["command"])] = out.Text
return out, nil
}
func (sh *shaping) agentTools(ctx context.Context, names []string) *tools.Tools {
return &tools.Tools{
Root: sh.root, Session: sh.s, Repo: agent.Git(sh.repo), Enabled: names,
Probe:         func(command string, files any) (string, error) { return sh.probe(ctx, command, files) },
Documentation: tools.Documentation{UserAgent: documentationAgent(sh.client)},
}
}
func documentationAgent(c *provider.Client) string {
if c != nil {
if f := strings.Fields(c.Version); len(f) > 1 {
return "kogen/" + f[1]
}
}
return "kogen/"
}
func (sh *shaping) probe(ctx context.Context, command string, files any, capture ...bool) (string, error) { panic("outside bounded native controls") }
func formatWall(w float64) string {
s := strconv.FormatFloat(w, 'f', -1, 64)
if !strings.Contains(s, ".") {
s += ".0"
}
return s
}
func (sh *shaping) submit(ctx context.Context, args map[string]any) (string, outcome, error) {
t := sh.ev.Millis()
defer func() { sh.ev.CheckSpan(t, sh.ev.Millis()) }()
if text, checked, err := sh.precheck(args); err != nil || checked {
return text, outcome{kind: outPrecheck}, err
}
sh.submissions++
sh.packageKey, sh.unchangedOf, sh.unchanged = "", 0, false
sh.priorRefusal, sh.lastCounted, sh.sameOf = sh.lastCounted, nil, 0
text, out, err := sh.submitOne(ctx, args)
if sh.incomplete && len(sh.declaredGaps(sh.proposed)) == 0 {
sh.incomplete = false
sh.incompleteRefusal = nil
}
if err == nil && out.kind == outObservations {
sh.unresolved = nil
}
return text, out, err
}
type shapeRefusal struct {
attempt  int
gate     string
problems []string
}
func (sh *shaping) earliestLines() []string {
if len(sh.unresolved) < 2 {
return nil
}
first, last := sh.unresolved[0], sh.unresolved[len(sh.unresolved)-1]
if first.gate == last.gate && slices.Equal(first.problems, last.problems) {
return nil
}
return append([]string{fmt.Sprintf("earliest unresolved refusal (attempt %d, gate %s):", first.attempt, first.gate)}, first.problems...)
}
func (sh *shaping) mergedPackage() string {
var b strings.Builder
for _, p := range sortedKeys(sh.proposed) {
fmt.Fprintf(&b, "%d:%s%d:%s", len(p), p, len(sh.proposed[p]), sh.proposed[p])
}
return ContentHash([]byte(b.String()))
}
func (sh *shaping) refused(gate string, problems []string) {
sh.lastGate = gate
if len(problems) > 20 {
problems = problems[:20]
}
cut := make([]string, len(problems))
for i, p := range problems {
if r := []rune(p); len(r) > 300 {
p = string(r[:300])
}
cut[i] = p
}
sh.lastRefusal = cut
refusal := shapeRefusal{attempt: sh.submissions, gate: gate, problems: cut}
sh.unresolved = append(sh.unresolved, refusal)
sh.lastCounted = &refusal
event := map[string]any{"event": "submission_refused", "attempt": sh.submissions, "gate": gate, "problems": cut}
if gate != "question_check" {
if sh.retry.limit == 0 {
sh.retry.limit = submissionRetryLimit(sh.in.SubmissionRetryLimit)
}
sh.retryStopped = sh.retry.refuse(gate)
event["consecutive"] = sh.retry.consecutive
event["total"] = sh.retry.total
}
sh.ev.Record(event)
}
const envelopeRule = "submit takes exactly one of a non-empty questions list, a non-empty files list, or a blocked report"
func (sh *shaping) refusedIncomplete(gate string, problems []string) {
sh.refused(gate, problems)
if p := sh.priorRefusal; p != nil && p.gate == gate && slices.Equal(p.problems, sh.lastRefusal) {
sh.sameOf = p.attempt
}
sh.incomplete = true
sh.incompleteRefusal = sh.lastCounted
sh.pending = sh.lastCounted
}
func (sh *shaping) invalidHead() string {
if sh.sameOf > 0 {
return fmt.Sprintf("invalid submission:\nThis is the same refusal as attempt %d; these items are unchanged:\n", sh.sameOf)
}
return "invalid submission:\n"
}
func (sh *shaping) declaredGaps(proposed map[string]string) []string {
absent := func(p string) bool {
if _, ok := proposed[p]; ok {
return false
}
fi, err := os.Stat(filepath.Join(sh.root, p))
return err != nil || !fi.Mode().IsRegular()
}
if absent(project.IntentMDPath(sh.slug)) {
return []string{"intent.md does not exist"}
}
intent, err := project.ReadIntent(sh.root, sh.slug, overlayOf(proposed))
if err != nil {
return nil
}
var gaps []string
feature := project.FeaturePath(sh.slug)
if absent(feature) {
gaps = append(gaps, "acceptance.feature does not exist")
}
seen := map[string]bool{feature: true}
for _, p := range intent.Acceptance {
if !seen[p] && absent(p) {
gaps = append(gaps, "acceptance: "+p+" does not exist")
}
seen[p] = true
}
if m := intent.Model; m != nil && !m.None && absent(m.Path) {
gaps = append(gaps, "model: "+m.Path+" does not exist")
}
return gaps
}
func (sh *shaping) precheck(args map[string]any) (string, bool, error) {
pc := sh.pending
if pc == nil {
return "", false, nil
}
sh.pending = nil
sub, problems, err := sh.validate(args)
if err != nil {
return "", false, err
}
var gaps []string
files := false
switch {
case problems != nil:
if problems[0] == envelopeRule {
gaps = problems
}
case sub.files != nil:
merged := maps.Clone(sh.proposed)
for _, f := range sub.files {
merged[f.path] = f.content
}
if gaps = sh.declaredGaps(merged); len(gaps) > 0 {
files = true
sh.proposed = merged
if err := sh.keepProposals(); err != nil {
return "", false, err
}
}
}
if len(gaps) == 0 {
return "", false, nil
}
sh.ev.Record(map[string]any{"event": "submission_precheck", "owner": "shape", "attempt": pc.attempt, "gaps": gaps})
first := "not submitted: the package still has these gaps, and this call was not counted as a submission attempt:"
if slices.Equal(gaps, pc.problems) {
first = fmt.Sprintf("not submitted: this is the same refusal as attempt %d; these items are unchanged, and this call was not counted as a submission attempt:", pc.attempt)
}
last := "No proposals from this call were retained; earlier proposals are unchanged. The next submission counts as an attempt."
if files {
last = "The files of this call were retained with your earlier proposals. Add what is missing with propose_files; the next submission counts as an attempt."
}
return first + "\n" + strings.Join(gaps, "\n") + "\n" + last, true, nil
}
func (sh *shaping) submitOne(ctx context.Context, args map[string]any) (string, outcome, error) {
sub, problems, err := sh.validate(args)
if err != nil {
return "", outcome{}, err
}
if problems != nil {
if problems[0] == envelopeRule {
sh.refusedIncomplete("validation", problems)
} else {
sh.refused("validation", problems)
}
return sh.invalidHead() + strings.Join(problems, "\n") +
"\nNo proposals from this submission were retained; earlier proposals are unchanged.",
outcome{kind: outInvalid, problems: problems}, nil
}
if !sub.blocked {
if text, out, refused, err := sh.decisionRecordGate(sub.decisions); err != nil {
return "", outcome{}, err
} else if refused {
return text, out, nil
}
}
switch {
case sub.questions != nil:
text, refused, err := sh.questionGate(ctx, sub.questions)
if err != nil {
return "", outcome{}, err
}
if refused != nil {
sh.refusedQuestionSets++
if sh.refusedQuestionSets >= questionRefusalLimit {
e := sys.Fail("shape", "question_refusals", fmt.Sprintf("shaping stopped after %d refused question sets; decide technical questions from the request and repository", questionRefusalLimit), 1)
e.Lines = append(slices.Clone(refused), sh.refusalCountsLines()...)
return "", outcome{}, e
}
return text, outcome{kind: outQuestionRefused, problems: refused}, nil
}
return "accepted", outcome{kind: outQuestions, questions: sub.questions}, nil
case sub.blocked:
return "blocked: required protected edits reported", outcome{kind: outBlocked, paths: sub.paths, reason: sub.reason}, nil
}
if problems := sh.publicationProblems(sub.files); len(problems) > 0 {
sh.refused("publication", problems)
return "invalid submission:\n" + strings.Join(problems, "\n") +
"\nNo proposals from this submission were retained; earlier proposals are unchanged.",
outcome{kind: outInvalid, problems: problems}, nil
}
text, out, err := sh.acceptFiles(ctx, sub.files)
if err == nil && out.kind == outReady {
if werr := os.WriteFile(filepath.Join(sh.ev.Dir, unresolvedFile), []byte("[]"), 0o600); werr != nil {
return "", outcome{}, werr
}
}
if err == nil && out.kind == outInvalid && sh.packageKey != "" {
if sh.unchangedOf > 0 {
sh.unchanged = true
text += fmt.Sprintf("\nUnchanged: this package is identical to the one refused at attempt %d; repair it before submitting again.", sh.unchangedOf)
} else {
if sh.refusedPackages == nil {
sh.refusedPackages = map[string]int{}
}
sh.refusedPackages[sh.packageKey] = sh.submissions
}
}
return text, out, err
}
func (sh *shaping) acceptFiles(ctx context.Context, submitted []proposedFile) (string, outcome, error) {
for _, f := range submitted {
sh.proposed[f.path] = f.content
}
p := project.IntentMDPath(sh.slug)
if draft, ok := sh.proposed[p]; ok {
sh.proposed[p] = repairCarriedDecisionDraft(sh.normalizeDecisionRounds(draft), sh.ledger.standing())
}
if err := sh.keepProposals(); err != nil {
return "", outcome{}, err
}
sh.packageKey = sh.mergedPackage()
sh.unchangedOf = sh.refusedPackages[sh.packageKey]
files := sortedKeys(sh.proposed)
if _, ok := sh.proposed[project.IntentMDPath(sh.slug)]; ok {
if intent, err := project.ReadIntent(sh.root, sh.slug, sh.overlay()); err == nil {
for _, p := range intent.StepFiles() {
if !slices.Contains(sh.declaredSteps, p) {
sh.declaredSteps = append(sh.declaredSteps, p)
}
}
}
}
intent, _, err := project.CheckIntent(sh.root, sh.slug, sh.overlay())
if err != nil && (sh.retry.total >= 2*submissionRetryLimit(sh.in.SubmissionRetryLimit)-1 ||
(sh.retry.gate == "intent" && sh.priorInvalid >= submissionRetryLimit(sh.in.SubmissionRetryLimit)-1) || submissionRetryLimit(sh.in.SubmissionRetryLimit) == 1) {
if e, ok := sys.AsError(err); ok && e.Reason == "lint" && slices.ContainsFunc(e.Lines, func(line string) bool { return strings.HasPrefix(line, "title:") }) {
p := project.IntentMDPath(sh.slug)
before := sh.proposed[p]
if first, rest, found := strings.Cut(before, "\n"); strings.HasPrefix(first, "# ") {
original := strings.TrimPrefix(first, "# ")
if titleLength(strings.TrimSpace(original)) > 50 {
short := shortenTitle(original)
sh.proposed[p] = "# " + short
if found {
sh.proposed[p] += "\n" + rest
}
if err := sh.keepProposals(); err != nil {
return "", outcome{}, err
}
sh.ev.Record(map[string]any{"event": "title_shortened", "original": original, "title": short})
intent, _, err = project.CheckIntent(sh.root, sh.slug, sh.overlay())
}
}
}
}
if err != nil {
e, ok := sys.AsError(err)
if !ok {
return "", outcome{}, err
}
lines := e.Lines
gaps := sh.declaredGaps(sh.proposed)
if len(gaps) > 0 && slices.Equal(lines, []string{"acceptance.feature does not exist"}) {
lines = gaps
}
if len(gaps) > 0 {
sh.refusedIncomplete("intent", lines)
} else {
sh.refused("intent", lines)
}
return sh.invalidHead() + strings.Join(lines, "\n") +
"\nEarlier well-formed proposals are retained; submit only corrections.",
outcome{kind: outInvalid, problems: lines}, nil
}
var ownership []string
stepsDir := ""
if sh.cfg.Acceptance != nil {
stepsDir = sh.cfg.Acceptance.StepsDir
}
for _, p := range intent.StepFiles() {
if !scopedStepPath(stepsDir, sh.slug, p) {
ownership = append(ownership, p+": use "+stepsDir+"/"+sh.slug+"__<suffix>.js with a nonempty suffix; put helper files in "+stepsDir+"/"+sh.slug+"__<suffix>/ (for example "+stepsDir+"/"+sh.slug+"__driver/main.go), list them under Acceptance and submit their contents")
} else if _, ok := sh.proposed[p]; !ok {
ownership = append(ownership, p+": submit this Intent's own step artifact; do not adopt existing step files")
}
others, _ := filepath.Glob(filepath.Join(sh.root, ".kogen/intents/*/intent.md"))
for _, op := range others {
otherSlug := filepath.Base(filepath.Dir(op))
if otherSlug == sh.slug {
continue
}
other, err := project.LoadIntent(sh.root, otherSlug)
if err == nil && slices.Contains(other.StepFiles(), p) {
ownership = append(ownership, fmt.Sprintf("%s belongs to Intent %s; %s must use its own step file", p, otherSlug, sh.slug))
}
}
}
if len(ownership) > 0 {
sh.refused("step_ownership", ownership)
return "invalid submission:\n" + strings.Join(ownership, "\n"), outcome{kind: outInvalid, problems: ownership}, nil
}
if problems := sh.retainedProblems(intent, files); len(problems) > 0 {
sh.refused("retained", problems)
return strings.Join(problems, "\n"), outcome{kind: outInvalid, problems: problems}, nil
}
return sh.checkSubmission(ctx, files)
}
func (sh *shaping) retainedProblems(intent *project.Intent, files []string) []string {
steps := intent.StepFiles()
model := ""
if intent.Model != nil && !intent.Model.None {
model = intent.Model.Path
}
var abandoned []string
for _, p := range files {
if (slices.Contains(sh.declaredSteps, p) && filepath.Ext(p) == ".js" && !slices.Contains(steps, p)) ||
(p == project.ModelPath(sh.slug) && p != model) {
abandoned = append(abandoned, p)
}
}
if len(abandoned) == 0 {
return nil
}
return []string{"proposed artifacts must remain declared: " + strings.Join(abandoned, ", ") + ". Omission cannot delete proposals; include them or preserve and park the partial package and its owned new step files, then remove its empty Intent directory and use normal shaping again (same slug or a new one)."}
}
func (sh *shaping) checkSubmission(ctx context.Context, files []string) (string, outcome, error) {
if err := sh.writeAttempt(files); err != nil {
return "", outcome{}, err
}
if err := sh.fixAttempt(ctx, files); err != nil {
return "", outcome{}, err
}
hash, err := sh.packageHash()
if err != nil {
return "", outcome{}, err
}
if text, out, refused := sh.contractRefusal(hash); refused {
return text, out, nil
}
if text, out, refused := sh.scopeRefusal(); refused {
return text, out, nil
}
written, err := os.ReadFile(filepath.Join(sh.root, project.IntentMDPath(sh.slug)))
if err != nil {
return "", outcome{}, err
}
if text, out, refused := sh.carriedDecisionsGate(string(written)); refused {
return text, out, nil
}
if text, out, refused, err := sh.evidenceGate(string(written)); err != nil {
return "", outcome{}, err
} else if refused {
return text, out, nil
}
evidence, err := sh.decisionEvidence(string(written))
if err != nil {
return "", outcome{}, err
}
evidenceHash := ContentHash([]byte(evidence))
if review := sh.readinessReview; review != nil && review.ready == sh.ready &&
review.packageHash == hash && review.evidenceHash == evidenceHash && sh.rd.Current(sh.s, sh.slug, sh.ready) {
sh.ev.Record(map[string]any{"event": "readiness_review_reused", "package": hash})
return "accepted: unchanged checked observations acknowledged", outcome{kind: outReady}, nil
}
sh.readinessReview = nil
sh.progress("kogen: checking step code")
feedback, err := sh.stepSelfcheck(ctx)
if err != nil {
return "", outcome{}, err
}
if feedback != "" {
problems := strings.Split(feedback, "\n")[1:]
sh.refused("step_selfcheck", problems)
return feedback, outcome{kind: outInvalid, problems: problems}, nil
}
lines, err := sh.decisionCheckWithEvidence(ctx, string(written), evidence)
if err != nil {
return "", outcome{}, err
}
if lines != nil {
sh.refused("decision_check", lines[1:])
return strings.Join(lines, "\n"), outcome{kind: outInvalid, problems: lines[1:]}, nil
}
lines, err = sh.literalCheck(ctx)
if err != nil {
return "", outcome{}, err
}
if lines != nil {
sh.refused("literal_check", lines[1:])
return strings.Join(lines, "\n"), outcome{kind: outInvalid, problems: lines[1:]}, nil
}
problems, err := sh.exampleCheck(ctx)
if err != nil {
return "", outcome{}, err
}
if len(problems) > 0 {
sh.refused("example_check", problems)
return "Examples contradict the rules:\n" + strings.Join(problems, "\n"), outcome{kind: outInvalid, problems: problems}, nil
}
if text, out, err := sh.staticChecks(ctx, hash); err != nil || out.kind == outInvalid {
return text, out, err
}
sh.progress("kogen: checking readiness")
text, result, err := sh.certify(ctx, files)
var unwritten *unwrittenTestsError
if errors.As(err, &unwritten) {
sh.refused("unwritten_tests", unwritten.items)
return unwritten.text(), outcome{kind: outInvalid, problems: unwritten.items}, nil
}
var observer *runnerObserverError
if errors.As(err, &observer) {
sh.refused("runner_observer", observer.items)
return observer.text(), outcome{kind: outInvalid, problems: observer.items}, nil
}
var preparation *preparationError
if errors.As(err, &preparation) {
sh.refused("preparation", preparation.items)
return preparation.text(), outcome{kind: outInvalid, problems: preparation.items}, nil
}
var unpassable *unpassableError
if errors.As(err, &unpassable) {
sh.refused("unpassable_step", unpassable.items)
return unpassable.text(), outcome{kind: outInvalid, problems: unpassable.items}, nil
}
if err != nil {
e, ok := sys.AsError(err)
if ok && (e.Reason == "not_ready" || e.Reason == "parse" || e.Reason == "lint") {
problems := e.Lines
if e.Reason != "not_ready" {
problems = append([]string{e.Error()}, e.Lines...)
}
sh.refused("readiness", problems)
return "not ready:\n" + strings.Join(problems, "\n"), outcome{kind: outInvalid, problems: problems}, nil
}
return "", outcome{}, err
}
if sh.lastFresh && !sh.contractChecked[hash] {
beforeContract := sh.ready
confirmed, err := sh.contractCheck(ctx, hash, sh.lastObservations)
if err != nil {
return "", outcome{}, err
}
if confirmed.empty() {
if confirmed, err = sh.wrongImplementationCheck(ctx, hash); err != nil {
return "", outcome{}, err
}
}
if !confirmed.empty() {
lines := confirmed.all()
sh.ready = nil
sh.contractRefused[hash] = confirmed
sh.contractLines = lines
sh.refused(contractGate, lines)
return contractFeedback(confirmed), outcome{kind: outInvalid, problems: lines}, nil
}
sh.contractChecked[hash] = true
if sh.ready != beforeContract {
if sh.ready.Failures() {
reference := filepath.Join(sh.root, sh.lastObservationsPath)
text, result = verify.Acknowledgment(sh.slug, sh.ready, reference), outcome{kind: outObservations}
} else {
return "accepted: the Intent is ready", outcome{kind: outReady}, nil
}
}
}
if result.kind == outObservations && sh.contractChecked[hash] {
sh.readinessReview = &readinessReview{ready: sh.ready, packageHash: hash, evidenceHash: evidenceHash}
}
return text, result, nil
}
func (sh *shaping) certify(ctx context.Context, files []string) (string, outcome, error) {
sh.lastFresh, sh.lastObservations = false, ""
if _, err := project.SourceComparison(sh.root, sh.slug); err != nil {
return "", outcome{}, err
}
if intent, _, err := project.CheckIntent(sh.root, sh.slug, nil); err == nil {
if problems := sh.retainedProblems(intent, files); len(problems) > 0 {
e := sys.Fail("intent", "lint", "the Intent needs changes", 1)
e.Lines = problems
return "", outcome{}, e
}
}
if sh.ready != nil && sh.rd.Current(sh.s, sh.slug, sh.ready) {
return "accepted: unchanged checked observations acknowledged", outcome{kind: outReady}, nil
}
var ready *verify.Ready
err := sh.ev.Timed("readiness", func() error {
var err error
ready, err = sh.rd.Check(ctx, sh.s, sh.slug)
return err
})
if err != nil {
return "", outcome{}, err
}
sh.ready = ready
reference := filepath.Join(sh.root, ".kogen/local/shaping", sh.slug, fmt.Sprintf("observations-%d.txt", sh.requests))
sh.lastObservationsPath = fmt.Sprintf(".kogen/local/shaping/%s/observations-%d.txt", sh.slug, sh.requests)
observations := verify.Observations(sh.slug, ready, reference)
if err := os.WriteFile(reference, []byte(observations), 0o666); err != nil {
return "", outcome{}, err
}
sh.lastFresh = true
if ready.Failures() {
sh.lastObservations = observations
return verify.Acknowledgment(sh.slug, ready, reference), outcome{kind: outObservations}, nil
}
return "accepted: the Intent is ready", outcome{kind: outReady}, nil
}
type unwrittenTestsError struct {
scenarios int
items     []string
}
func (e *unwrittenTestsError) Error() string { return strings.SplitN(e.text(), "\n", 2)[0] }
func (e *unwrittenTestsError) text() string {
return fmt.Sprintf("Acceptance depends on tests the Build would have to invent: %d scenario(s) run named tests that do not exist before the Build; nothing was published. "+
"Acceptance must observe behaviour that any correct implementation produces (run the program, call the code or inspect its output), "+
"not test names or files the Build has to write. Rewrite these steps; resubmitting them unchanged is refused again.", e.scenarios) +
"\n" + strings.Join(e.items, "\n")
}
func unwrittenTestsGate(ready *verify.Ready) error {
e := &unwrittenTestsError{}
for _, sc := range ready.Scenarios {
if sc.Status != "failed" || len(sc.Unwritten) == 0 {
continue
}
e.scenarios++
for _, l := range sc.Unwritten {
e.items = append(e.items, fmt.Sprintf("- %s (line %d): %s", sc.Name, sc.Line, l))
}
}
if e.scenarios == 0 {
return nil
}
return e
}
type runnerObserverError struct {
scenarios int
items     []string
}
func (e *runnerObserverError) Error() string { return strings.SplitN(e.text(), "\n", 2)[0] }
func (e *runnerObserverError) text() string {
return fmt.Sprintf("Acceptance rejects the test runner's real output: %d scenario(s) fail although the test runner reported a passing run, or pass an anchored regular expression as a name filter the runner matches literally; nothing was published. "+
"A step that observes a test runner must accept the summary the runner really prints on the unchanged tree "+
"and give a literal name filter only the plain test name. Rewrite these steps; resubmitting them unchanged is refused again.", e.scenarios) +
"\n" + strings.Join(e.items, "\n")
}
func readinessGate(ready *verify.Ready) error {
if err := unwrittenTestsGate(ready); err != nil {
return err
}
return runnerObserverGate(ready)
}
func runnerObserverGate(ready *verify.Ready) error {
e := &runnerObserverError{}
for _, sc := range ready.Scenarios {
if sc.Status != "failed" || sc.RunnerObserver == "" {
continue
}
e.scenarios++
e.items = append(e.items, fmt.Sprintf("- %s (line %d): %s", sc.Name, sc.Line, sc.RunnerObserver))
}
if e.scenarios == 0 {
return nil
}
return e
}
func (sh *shaping) writeAttempt(files []string) error {
for _, p := range files {
if _, ok := sh.originals[p]; ok {
continue
}
old, err := os.ReadFile(filepath.Join(sh.root, p))
sh.originals[p] = original{content: old, absent: err != nil}
}
for _, p := range files {
path := filepath.Join(sh.root, p)
if err := os.MkdirAll(filepath.Dir(path), 0o777); err != nil {
return err
}
if err := os.WriteFile(path, []byte(sh.proposed[p]), 0o666); err != nil {
return err
}
}
return nil
}
func (sh *shaping) fixAttempt(ctx context.Context, paths []string) error { return nil }
type submission struct {
questions []map[string]any
decisions []sourcedDecision
files     []proposedFile
blocked   bool
paths     []string
reason    string
}
type proposedFile struct{ path, content string }
func isText(v any) bool {
s, ok := v.(string)
return ok && strings.TrimSpace(s) != ""
}
func (sh *shaping) validate(args map[string]any) (submission, []string, error) {
sub, problems, err := sh.validateEnvelope(args)
if err != nil || (problems != nil && problems[0] == envelopeRule) {
return sub, problems, err
}
list, present, ok := decisionsOf(args)
switch {
case !present:
return sub, problems, nil
case hasBlocked(args):
problems = append(problems, decisionsWithBlocked)
case !ok:
problems = append(problems, decisionsMalformed)
case problems == nil:
sub.decisions = list
}
if problems != nil {
sub = submission{}
}
return sub, problems, nil
}
func hasBlocked(args map[string]any) bool {
_, has := args["blocked"]
return has
}
func (sh *shaping) validateEnvelope(args map[string]any) (submission, []string, error) {
_, hasQ := args["questions"]
_, hasF := args["files"]
blocked, hasB := args["blocked"]
qs, _ := args["questions"].([]any)
fs, _ := args["files"].([]any)
switch {
case hasB && !hasQ && !hasF:
return sh.validateBlocked(blocked)
case len(qs) > 0 && !hasF && !hasB:
return validateQuestions(args, qs)
case len(fs) > 0 && !hasQ && !hasB:
return sh.validateFiles(fs)
}
return submission{}, []string{envelopeRule, "received: " + receivedShape(args)}, nil
}
func receivedShape(args map[string]any) string {
var parts []string
for _, key := range []string{"questions", "files", "blocked"} {
v, ok := args[key]
if !ok {
continue
}
kind := "object"
switch v := v.(type) {
case []any:
kind = fmt.Sprintf("list of %d", len(v))
case string:
kind = "text"
case bool:
kind = "boolean"
case nil:
kind = "null"
case map[string]any:
default:
kind = "number"
}
parts = append(parts, key+" ("+kind+")")
}
if len(parts) == 0 {
return "none of questions, files or blocked"
}
return strings.Join(parts, ", ")
}
func (sh *shaping) validateBlocked(blocked any) (submission, []string, error) { panic("outside bounded native controls") }
func validateQuestions(args map[string]any, qs []any) (submission, []string, error) { panic("outside bounded native controls") }
func explicitRejectedKind(kind any) bool {
switch kind {
case nil, "product", "handoff":
return false
}
return true
}
const optionsRule = "every question needs at least two options with distinct, non-empty labels and at most one option marked recommended"
func optionProblemsOf(q map[string]any) []string { panic("outside bounded native controls") }
func validOptions(q map[string]any) bool {
raw, has := q["options"]
if !has || raw == nil {
return true
}
options, ok := raw.([]any)
if !ok {
return false
}
for _, o := range options {
m, ok := o.(map[string]any)
if !ok {
return false
}
if _, ok := m["label"].(string); !ok {
return false
}
if r, has := m["recommended"]; has {
if _, ok := r.(bool); !ok {
return false
}
}
}
return true
}
func (sh *shaping) validateFiles(list []any) (submission, []string, error) {
slug := sh.slug
own := []string{project.IntentMDPath(slug), project.FeaturePath(slug), project.ModelPath(slug), project.IntentDir(slug) + "/controls.json"}
steps := ""
if sh.cfg.Acceptance != nil {
steps = sh.cfg.Acceptance.StepsDir
}
var problems []string
var files []proposedFile
seen := map[string]bool{}
extra := map[string]bool{}
for p := range sh.proposed {
if intentFolderFile(slug, own, p) {
extra[p] = true
}
}
for _, f := range list {
m, _ := f.(map[string]any)
p, pok := m["path"].(string)
c, cok := m["content"].(string)
if !pok || !cok {
problems = append(problems, "every file needs a path and a content string")
continue
}
switch {
case !normalPath(p):
problems = append(problems, p+": paths must be relative and normal")
case slices.Contains(own, p):
case intentFolderFile(slug, own, p):
if len(c) > maxIntentFolderFileBytes {
problems = append(problems, fmt.Sprintf("%s: a file under %s/ may hold at most %d bytes", p, project.IntentDir(slug), maxIntentFolderFileBytes))
}
extra[p] = true
case steps != "" && strings.HasPrefix(p, steps+"/"):
if !scopedStepPath(steps, slug, p) {
problems = append(problems, p+": new step files must be named "+steps+"/"+slug+"__<suffix>.js (nonempty suffix); prefix step sentences and definitions with "+slug+": ")
}
default:
where := steps
if steps == "" {
where = "commands.acceptance.steps_dir (unset)"
}
problems = append(problems, p+": shaping may write only files under "+project.IntentDir(slug)+"/ and step files under "+where+"/")
}
seen[p] = true
files = append(files, proposedFile{p, c})
}
if len(extra) > maxIntentFolderFiles {
problems = append(problems, fmt.Sprintf("shaping may write at most %d files under %s/ besides intent.md, acceptance.feature, model.qnt and controls.json", maxIntentFolderFiles, project.IntentDir(slug)))
}
if len(problems) > 0 {
return submission{}, problems, nil
}
if len(seen) != len(list) {
return submission{}, []string{"file paths must be unique; no proposals from this submission were retained"}, nil
}
sort.Slice(files, func(i, j int) bool { return files[i].path < files[j].path })
return submission{files: files}, nil, nil
}
const (
maxIntentFolderFiles     = 16
maxIntentFolderFileBytes = 65536
)
func intentFolderFile(slug string, own []string, p string) bool {
return strings.HasPrefix(p, project.IntentDir(slug)+"/") && normalPath(p) && !slices.Contains(own, p)
}
func normalPath(p string) bool {
if p == "" || strings.HasPrefix(p, "/") || p == "~" || strings.HasPrefix(p, "~/") {
return false
}
norm := filepath.Clean(filepath.Join("/r", p))
rel, ok := strings.CutPrefix(norm, "/r/")
return ok && rel == p
}
func (sh *shaping) printBlocked(res outcome) int {
sh.s.Puts("shape/protected_conflict: required edits touch protected files: " + strings.Join(res.paths, ", "))
sh.s.Puts(res.reason)
sh.s.Puts("Next: revise the request, or review and commit .kogen/project.yaml outside Build, then shape again; preserve checks and actual check configuration. There is no protected-edit override.")
return 1
}
func (sh *shaping) printReady(added []string, usageLine string) int {
